import{_ as e,o as r,c as t,a3 as l}from"./chunks/framework.C8xYrcAN.js";const u=JSON.parse('{"title":"联系我们","description":"Chaldea 联系方式、隐私问题与权利请求、问题反馈及社区交流渠道。","frontmatter":{"title":"联系我们","description":"Chaldea 联系方式、隐私问题与权利请求、问题反馈及社区交流渠道。"},"headers":[],"relativePath":"zh/guide/contact.md","filePath":"zh/guide/contact.md","lastUpdated":1792948524000}'),i={name:"zh/guide/contact.md"};function o(n,a,s,c,h,p){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h1><p>如果你在使用 Chaldea 时遇到问题、需要账号协助，或希望提出建议、隐私投诉及个人信息权利请求，可以通过以下渠道联系我们。</p><h2 id="邮件联系" tabindex="-1">邮件联系 <a class="header-anchor" href="#邮件联系" aria-label="Permalink to &quot;邮件联系&quot;">​</a></h2><p>邮箱：<a href="mailto:support@chaldea.center" target="_blank" rel="noreferrer">support@chaldea.center</a></p><p>账号问题、隐私投诉及涉及个人资料的请求，建议通过邮件联系。请勿在公开问题单或社区中发布密码、Token、验证码等敏感信息。</p><h2 id="privacy-contact" tabindex="-1">隐私问题与权利请求 <a class="header-anchor" href="#privacy-contact" aria-label="Permalink to &quot;隐私问题与权利请求 {#privacy-contact}&quot;">​</a></h2><p>如需查阅、复制、更正、补充或删除个人信息、撤回同意、注销账号，或对个人信息处理提出异议，请通过<a href="mailto:support@chaldea.center" target="_blank" rel="noreferrer">邮件</a>联系我们。相关处理规则见<a href="./privacy">隐私政策</a>。</p><p>为便于处理，请说明：</p><ul><li>请求类型，以及需要我们协助的具体事项。</li><li>如请求与账号有关，可提供用户名等定位所需信息；我们仅在核实请求所必要的范围内进一步确认身份。</li></ul><p>隐私请求不默认要求你提供日志、截图或完整用户数据；请勿发送密码、Token 或验证码。</p><p>我们将在收到隐私投诉或权利请求后 <strong>15 个工作日内答复</strong>；无法直接办理的，将说明原因与可行途径。该答复时限适用于隐私事项。</p><h2 id="问题与建议" tabindex="-1">问题与建议 <a class="header-anchor" href="#问题与建议" aria-label="Permalink to &quot;问题与建议&quot;">​</a></h2><ul><li><strong>应用内反馈</strong>：通过“设置 → 反馈”提交技术问题或建议。应用内反馈会附带诊断日志和用户数据文件；隐私权利请求建议使用邮件渠道。</li><li><strong>GitHub Issues</strong>：在 <a href="https://github.com/chaldea-center/chaldea/issues" target="_blank" rel="noreferrer">Chaldea Issues</a> 报告可公开讨论的问题或功能建议。提交前可先搜索已有问题，避免重复。</li></ul><p>GitHub Issues 是公开平台。公开提交截图或日志前，请移除账号资料及其他敏感信息；无需在公开问题单中留下个人邮箱。</p><h2 id="社区交流" tabindex="-1">社区交流 <a class="header-anchor" href="#社区交流" aria-label="Permalink to &quot;社区交流&quot;">​</a></h2><ul><li><a href="https://discord.gg/5M6w5faqjP" target="_blank" rel="noreferrer">Discord 社区</a></li><li><a href="https://bbs.nga.cn/read.php?tid=24926789" target="_blank" rel="noreferrer">NGA FGO 社区主题</a></li></ul><p>社区适合一般讨论和经验交流。账号资料、隐私投诉及个人信息权利请求请通过邮件联系。</p><h2 id="反馈信息准备" tabindex="-1">反馈信息准备 <a class="header-anchor" href="#反馈信息准备" aria-label="Permalink to &quot;反馈信息准备&quot;">​</a></h2><p>报告技术问题时，尽量提供以下信息：</p><ul><li>App 版本、数据版本、设备型号及系统版本。</li><li>出现问题的页面、复现步骤、预期结果和实际结果。</li><li>与问题有关、已移除敏感信息的截图或日志（如有）。</li></ul><p>提出功能建议时，请说明使用场景、目前遇到的困难及期望行为。通过邮件或应用内反馈提交后，如希望收到回复，请提供可用的联系方式。</p>',21)])])}const f=e(i,[["render",o]]);export{u as __pageData,f as default};
